local ActivityNewYearFundDialog = Class("ActivityNewYearFundDialog")

function ActivityNewYearFundDialog:__init() 
    self._data = nil
    self._activityData = nil
    self._listData = {}
    self._fundVo = nil
    self.goodsId = nil
end 

function ActivityNewYearFundDialog:__delete()
    self._data = nil
    self._activityData = nil
    self._listData = {}
    self._fundVo = nil
    self.goodsId = nil
end

function ActivityNewYearFundDialog:Awake()
    self.__EventSdkEvent = Events.AddListener(Constants.EventNames.EVENT_SDK, Bind(self, self.OnEventSdkEvent))
    SetButtonAction(self.BtnBuy, Bind(self, self.OnBtnPay))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnOneKeyDraw))

    SetButtonAction(self.BtnLook, Bind(self, self.OnBtnLook))
    SetButtonAction(self.AvailableBtnNode, Bind(self, self.OnDrawBox))
end

function ActivityNewYearFundDialog:InitData()
    local t = newYearFundComponent:GetActivityConf()
    local id = t.id
    id = id or 1
    self._fundVo = NewYearFundUtils.GetNewYearFundVo(id)
    if not self._fundVo then
        return
    end

    self._listData =  CfUtils.GetIdGroupData(AutoIds.IdSetting6711, id)
end

function ActivityNewYearFundDialog:Refresh(data)
    if isNull(data) then
        return
    end

    self._data = data
    self._activityData = NewYearFundUtils.GetActivityData()
    if not self._activityData then
        return
    end

    GameUtils.Request(Interfaces.ActivityNewYearFundHome, {activityUuid = self._activityData.id}, function(request, response)
        if checkInt(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        newYearFundComponent:Initial(jsonData, self._activityData.id)

        self:InitData()
        self:FillSelf()
        self:FillBaseInfo()

        GameUtils.SetRedPointNum(Constants.RedPointConst.NewYearFund, NewYearFundUtils.IsHaveCanDrawReward(self._fundVo.id) and 1 or 0)
    
        local ani = self.Root.gameObject:GetComponent(typeof(Animator))
        ani:SetBool("Reward", checkBool(NewYearFundUtils.IsCanDrawBox())) 
    end)
end

function ActivityNewYearFundDialog:FillBaseInfo()
    CfUtils.FillWebRawImage(self.ImgTitleName, self._activityData.titleImage)
    --CfUtils.FillWebRawImage(self.ImgTitleName2, self._activityData.titleImage)

    print(table.dump(self._activityData))
    CfUtils.FillText(self.TxtTime, self:GetTime(self._activityData.startTime, self._activityData.endTime))
    CfUtils.FillText(self.TxtNumber, newYearFundComponent:GetSignDay())
    CfUtils.FillText(self.TxtContent, self._activityData.detail)

    local payInfo = newYearFundComponent:GetProducts()
    if self:IsGoodsPay() then
        CfUtils.SetActive(self.BtnBuy.transform:Find("ImgIcon") , true)
        for goodsId, v in pairs(payInfo.prices) do
            local goodPath = GoodsConfMgr:GetInstance():GetPhotoPathById(goodsId)
            self.goodsId = goodsId
            CfUtils.FillImage(self.BtnBuy.transform:Find("ImgIcon").gameObject , goodPath)
            CfUtils.FillText(self.BtnBuy.transform:Find("Txtnum"),v.current)
        end
        self:RefreshCurrencyBarInfo()
    else
        CfUtils.SetActive(self.BtnBuy.transform:Find("ImgIcon") , false)
        CfUtils.FillText(self.BtnBuy.transform:Find("Txtnum"), CfUtils.GetDisplayPrice(payInfo.windowsPriceId, payInfo.channelProductId))
    end
end

function ActivityNewYearFundDialog:RefreshCurrencyBarInfo()
    if self._listData and self.goodsId then
        ActivityUtils.RefreshNavigatorGoods({self.goodsId})
    end
end

function ActivityNewYearFundDialog:GetTime(startTime, endTime)
    return os.date("%Y/%m/%d", startTime).."-"..os.date("%Y/%m/%d  %H:%M", endTime)
end

function ActivityNewYearFundDialog:FillSelf()
    CfUtils.SetActive(self.LockNode, not newYearFundComponent:GetIsPay())

    CfUtils.SetActive(self.BuyNode, not newYearFundComponent:GetIsPay())
    self:FillList()
    self:FillBox()
end

function ActivityNewYearFundDialog:FillBox()
    local isDraw = newYearFundComponent:GetIsDrawBox()
    CfUtils.SetActive(self.LeftDecorate, isDraw)
    CfUtils.SetActive(self.LeftBuy, not isDraw)

    if not isDraw then
        local isCanDraw = newYearFundComponent:GetIsPay()
        CfUtils.SetActive(self.AvailableBtnNode, isCanDraw)
        CfUtils.SetActive(self.NotBuyNode, not isCanDraw)
    end
end

function ActivityNewYearFundDialog:FillList()
    if self._isInitList then
        GameUtils.ReloadData(self.ScrollView, table.count(self._listData))
    else
        self.ScrollView:InitListView(#self._listData, Bind(self, self.OnGetCellByIndex))
        self._isInitList = true
    end
end

function ActivityNewYearFundDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._listData[index + 1]
    local cell = listView:NewListViewItem("Cell") 
    local scr = CfUtils.GetLuaScr(cell.gameObject, "Game.UI.ActivityNewYearFund.ActivityNewYearFundCell")
    if scr then
        scr:Refresh(data)
    end
    return cell
end

function ActivityNewYearFundDialog:OnBtnOneKeyDraw()
    local isHaveReward = NewYearFundUtils.IsHaveCanDrawReward(self._fundVo.id)
    if not isHaveReward then
        GameUtils.Toast(localize("无奖励可领取"))
        return
    end

    newYearFundComponent:ActivityNewYearFundReceiveRewardReq("", function()
        self:FillSelf()    
    end)
end


function ActivityNewYearFundDialog:OnBtnLook()
    UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityNewYearFundLookPopup, parameters = {id = self._fundVo.id} })
end

function ActivityNewYearFundDialog:OnDrawBox()
    local isDraw = newYearFundComponent:GetIsDrawBox()
    if isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end
    local isCanDraw = newYearFundComponent:GetIsPay()
    if not isCanDraw then
        GameUtils.Toast(localize("未解锁"))
        return
    end

    newYearFundComponent:DrawBoxReq(function()
        self:FillSelf()    

        local ani = self.Root.gameObject:GetComponent(typeof(Animator))
        ani:SetBool("Reward", false)
        CfUtils.PlayAnimator(self.Root, "Go")
    end)
end

function ActivityNewYearFundDialog:IsGoodsPay()
    local payInfo = newYearFundComponent:GetProducts()
    return next(checkTable(payInfo.prices)) ~= nil
end

function ActivityNewYearFundDialog:OnBtnPay()
    --if true then
    --    newYearFundComponent._isPay = 1
    --    Events.Broadcast(Constants.EventNames.EVENT_SDK, {event = Constants.EventNames.EVENT_SDK_PAY})
    --    return
    --end
    local payInfo = newYearFundComponent:GetProducts()
    if self:IsGoodsPay() then
        local goodsId = checkNumber(table.takeFirst(table.keys(payInfo.prices)))
        local dojo = payInfo.prices[tostring(goodsId)]
        local productId = payInfo.productId
        if dojo then
            local price = checkNumber(dojo.current)
            ---@type ServerDifferenceMgr
            local ServerDifferenceMgr = import('Game.Setting.ServerDifferenceMgr'):GetInstance()
            ServerDifferenceMgr:WrapPrimaryCurrencyBuy({
                currency = goodsId,
                current = price,
            }, function(isSuccess)
                isSuccess = checkBool(isSuccess)
                if not isSuccess then
                    return
                end
                ----请求兑换的逻辑
                GameUtils.Request("ActivityNewYearFund/diamondBuy", {activityUuid = self._activityData.id}, function(request, resp)
                    if checkNumber(resp.errCode) == 0 then
                        local reward = checkTable(resp.data.rewards)
                        GoodsUtils.DrawRewards({ {
                                                     goodsId = goodsId,
                                                     num = - price,
                                                     productId = productId,
                                                 } })
                        if #reward > 0 then
                            GoodsUtils.DrawRewards(reward)
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = reward } })
                        end
                        newYearFundComponent._isPay = 1             --支付完必定是1
                        self:FillSelf()
                    end
                end)
            end)
        end
    else
        SDKService:GetInstance():PayMoney({
            productId = payInfo.productId,
            channelProductId = payInfo.channelProductId,
            productDesc = localize("新年基金"),
            payAmount = payInfo.price,
            data = payInfo
        })
    end
end

--支付成功
function ActivityNewYearFundDialog:OnEventSdkEvent(parameters)
    --- sdk pay succeed
    if parameters.event == Constants.EventNames.EVENT_SDK_PAY then
        newYearFundComponent._isPay = 1             --支付完必定是1
        self:FillSelf()    
    end
end

function ActivityNewYearFundDialog:OnDestroy()
    GameUtils.SetRedPointNum(Constants.RedPointConst.NewYearFund, NewYearFundUtils.IsHaveCanDrawReward(self._fundVo.id) and 1 or 0)
    if self.__EventSdkEvent then
        Events.RemoveListener(Constants.EventNames.EVENT_SDK, self.__EventSdkEvent)
        self.__EventSdkEvent = nil
    end

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return ActivityNewYearFundDialog
